    #include <vector>
#include <algorithm>
#include <iostream>
using namespace std;

vector<int> getMinMax(vector<int>& arr, int low, int high) {
    vector<int> result(2);

    // Base case: single element
    if (low == high) { 
        result[0] = arr[low];
        result[1] = arr[low];
        return result;
    }

    // Base case: two elements
    if (high == low + 1) { 
        if (arr[low] < arr[high]) {
            result[0] = arr[low];
            result[1] = arr[high];
        } else {
            result[0] = arr[high];
            result[1] = arr[low];
        }
        return result;
    }

    int mid = (low + high) / 2;

    // Recurse on left half
    vector<int> left = getMinMax(arr, low, mid); 

    // Recurse on right half
    vector<int> right = getMinMax(arr, mid + 1, high); 

    // Combine min
    result[0] = min(left[0], right[0]); 

    // Combine max
    result[1] = max(left[1], right[1]); 

    return result;
}

vector<int> findMinMax(vector<int>& arr) {
    return getMinMax(arr, 0, arr.size() - 1);
}

int main() {
    vector<int> arr = {3, 5, 4, 1, 9};
    vector<int> result = findMinMax(arr);
    cout << result[0] << " " << result[1] << endl;
    return 0;
}


