[Optimal Approach] Comparing in pairs - O(n) Time and O(1) SpaceThis approach finds the smallest and largest numbers in a list by reducing the number of comparisons. If the list has an odd number of elements, it initializes both the minimum and maximum with the first element. If it has an even number, it compares the first two elements to set the initial min and max. It then processes the remaining elements in pairs. For each pair, it identifies the smaller and larger number, then updates the current minimum and maximum accordingly. After all pairs are checked, the final minimum and maximum values are returned.Number of Comparisons:If n is odd:First element sets both min and max (no comparison).Remaining n - 1 elements are processed in pairs.Each pair takes 3 comparisons (between elements, and with min and max).Total comparisons: 3 * (n - 1) / 2.If n is even:First two elements compared once to set min and max.Remaining n - 2 elements processed in pairs (3 comparisons per pair).Total comparisons: 1 + 3 * (n - 2) / 2 = (3 * n) / 2 - 2.Below is the implementation of the above approach:
            C++

    #include <vector>
#include <climits>
#include <iostream>
using namespace std;

vector<int> findMinMax(const vector<int>& arr) {
    int n = arr.size();
    int mini, maxi, i;

    // Initialize min and max
    if (n % 2 == 1) {
        mini = maxi = arr[0];
        i = 1;
    } else {
        if (arr[0] < arr[1]) {
            mini = arr[0];
            maxi = arr[1];
        } else {
            mini = arr[1];
            maxi = arr[0];
        }
        i = 2;
    }

    // Process elements in pairs
    while (i < n - 1) {
        if (arr[i] < arr[i + 1]) {
            mini = min(mini, arr[i]);
            maxi = max(maxi, arr[i + 1]);
        } else {
            mini = min(mini, arr[i + 1]);
            maxi = max(maxi, arr[i]);
        }
        i += 2;
    }

    return {mini, maxi};
}

int main() {
    vector<int> arr = {3, 5, 4, 1, 9};
    vector<int> result = findMinMax(arr);
    if (!result.empty()) {
        cout << result[0] << " " << result[1] << endl;
    }
    return 0;
}


